//! 📤️ Original accepted metadata and first-party props enter paid slot, identity and token production without a semantic mirror.
use super::{PresentedMediaSlot,PresentedMediaRect,PresentedMediaOwner};
use semio_framework_job::{StepContext,OriginalTurnFailure};
use semio_framework_value::{DslValue,ValueError,ValueRefusalKind,RetainedCloneProgress,RetirementDemand,NativeEncodeControl,NativeEncodeContinuation,retirement::controlled::ControlledRetirement};
use semio_framework_pack_json::{JsonBorrowedWriteCursor,JsonWriteSource,JsonWriteNode};

pub struct PresentedSlotSource<'a>{pub window:&'a str,pub node_id:u64,pub key:&'a str,pub owner:&'a PresentedMediaOwner,pub rect:PresentedMediaRect,pub clip:PresentedMediaRect,pub order:u32,pub occluded:bool}
impl PresentedSlotSource<'_>{fn scalar(&self)->(u32,[u32;8],u32,bool){(self.owner.app_instance_id,[self.rect.x,self.rect.y,self.rect.width,self.rect.height,self.clip.x,self.clip.y,self.clip.width,self.clip.height].map(f32::to_bits),self.order,self.occluded)}fn identity(&self)->[(usize,usize);5]{[self.window,self.key,&self.owner.plugin_id,&self.owner.controller_id,&self.owner.parent_document_id].map(|value|(value.as_ptr()as usize,value.len()))}fn field(&self,index:usize)->&str{match index{0=>self.window,2=>self.key,3=>&self.owner.plugin_id,4=>&self.owner.controller_id,5=>&self.owner.parent_document_id,_=>unreachable!("original numeric field is inline")}}}
fn allocation(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::AllocationFailed,message)}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn permits(cx:&StepContext<'_>,demand:RetirementDemand)->bool{let grant=cx.retained_grant();!cx.should_yield()&&grant.maximum_items>0&&grant.maximum_depth>=demand.depth&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes}
fn metadata(cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Ok(())}
fn close<T:semio_framework_value::RetireOwned>(owner:&mut ControlledRetirement<T>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if owner.terminal_is_empty(){return Ok(true)}let demand=owner.selected_demand(cx.retained_grant().maximum_copy_bytes)?;let _=semio_framework_job::close_original_retained_step(cx,demand,|grant|owner.step(grant))?;Ok(owner.terminal_is_empty())}

pub struct OriginalPresentedSlot{source:[(usize,usize);5],node:u64,scalar:(u32,[u32;8],u32,bool),identity:(semio_framework_job::OperationId,semio_framework_job::Generation),clock:fn()->Option<u64>,deadline:u64,phase:u8,field:usize,position:usize,characters:usize,reserved:bool,decimal:[u8;20],decimal_start:usize,payload:ControlledRetirement<Option<PresentedMediaSlot>>,buffer:ControlledRetirement<Vec<u8>>,writer:ControlledRetirement<JsonBorrowedWriteCursor>,encoding:Option<NativeEncodeContinuation>,wire:ControlledRetirement<Option<String>>,hash:Option<semio_framework_hash::Sha256>,digest:[u8;32],closing:bool}
impl OriginalPresentedSlot{
 pub fn admit(target:&mut Option<Self>,source:&PresentedSlotSource<'_>,props:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if target.is_some(){return Err(invalid("original slot producer receiver is occupied").into())}
  if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}
  if props.is_none(){return Err(invalid("original slot requires its paid props owner").into())}
  let mut decimal=[0;20];let mut decimal_start=20;let mut value=source.node_id;loop{decimal_start-=1;decimal[decimal_start]=b'0'+(value%10)as u8;value/=10;if value==0{break}}
  let slot=PresentedMediaSlot{token:String::new(),window_id:String::new(),node_id:String::new(),node_key:String::new(),rect:source.rect.clone(),clip:source.clip.clone(),paint_order:source.order,occluded:source.occluded,plugin_id:String::new(),controller_id:String::new(),app_instance_id:source.owner.app_instance_id,parent_document_id:String::new(),props:props.take().unwrap()};
  let owner=Self{source:source.identity(),node:source.node_id,scalar:source.scalar(),identity:(cx.operation(),cx.generation()),clock:cx.clock_source(),deadline:cx.deadline_us(),phase:0,field:0,position:0,characters:0,reserved:false,decimal,decimal_start,payload:ControlledRetirement::new(Some(slot)).unwrap_or_else(|_|unreachable!()),buffer:ControlledRetirement::new(Vec::new()).unwrap_or_else(|_|unreachable!()),writer:ControlledRetirement::new(JsonBorrowedWriteCursor::new()).unwrap_or_else(|_|unreachable!()),encoding:None,wire:ControlledRetirement::new(None).unwrap_or_else(|_|unreachable!()),hash:Some(semio_framework_hash::Sha256::new()),digest:[0;32],closing:false};*target=Some(owner);metadata(cx)?;Ok(true)
 }
 fn check_caller(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.identity!=(cx.operation(),cx.generation())||!std::ptr::fn_addr_eq(self.clock,cx.clock_source())||self.deadline!=cx.deadline_us(){return Err(invalid("original slot caller clock or deadline changed"))}Ok(())}
 pub fn advance(&mut self,source:&PresentedSlotSource<'_>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.check_caller(cx)?;if self.closing||self.source!=source.identity()||self.node!=source.node_id||self.scalar!=source.scalar(){return Err(invalid("accepted slot source identity changed").into())}
  if self.phase==7{return Ok(true)}
  if self.phase==0{
   let bytes=if self.field==1{&self.decimal[self.decimal_start..]}else{source.field(self.field).as_bytes()};
   if !self.reserved{let maximum=match self.field{0|2|5=>512,3|4=>256,_=>20};if bytes.len()>maximum*4{if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}metadata(cx)?;return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original accepted slot source extent exceeds the native transport bound").into())}let demand=RetirementDemand{capacity_bytes:bytes.len(),depth:1,..Default::default()};if !permits(cx,demand){return Ok(false)}let buffer=self.buffer.original_mut().ok_or_else(||invalid("slot copy buffer is retiring"))?;let result=buffer.try_reserve_exact(bytes.len());let progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:buffer.capacity(),..Default::default()};let receipt=cx.consume_retained(progress).err();cx.consume_fuel(1);self.reserved=true;return match(result,receipt){(Ok(()),None)=>Ok(false),(Err(_),receipt_refusal)=>Err(OriginalTurnFailure{primary:allocation("original slot text allocation failed").with_retained_progress(progress).into(),receipt_refusal,context_refusal:None}),(Ok(()),Some(refusal))=>Err(refusal.into())}}
   if self.position<bytes.len(){if !permits(cx,RetirementDemand{copy_bytes:1,depth:1,..Default::default()}){return Ok(false)}let byte=bytes[self.position];self.buffer.original_mut().unwrap().push(byte);self.position+=1;if byte&0xc0!=0x80{self.characters+=1;}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()})?;cx.consume_fuel(1);let maximum=match self.field{0|2|5=>512,3|4=>256,_=>20};if self.characters>maximum{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original accepted slot text exceeds the native transport bound").into())}return Ok(false)}
   if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}if self.characters==0{metadata(cx)?;return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original accepted slot text is empty").into())}let bytes=self.buffer.take_original().ok_or_else(||invalid("slot source buffer lost original custody"))?;let text=unsafe{String::from_utf8_unchecked(bytes)};let slot=self.payload.original_mut().unwrap().as_mut().unwrap();match self.field{0=>slot.window_id=text,1=>slot.node_id=text,2=>slot.node_key=text,3=>slot.plugin_id=text,4=>slot.controller_id=text,5=>slot.parent_document_id=text,_=>unreachable!()};self.field+=1;self.position=0;self.characters=0;self.reserved=false;self.buffer=ControlledRetirement::new(Vec::new()).unwrap_or_else(|_|unreachable!());if self.field==6{self.phase=1}metadata(cx)?;return Ok(false)
  }
  if self.phase==1{
   let token=SlotIdentity(self.payload.original().unwrap().as_ref().unwrap());let writer=self.writer.original_mut().ok_or_else(||invalid("slot identity writer is retiring"))?;let demand=writer.normal_step_demands(&token)?;if !permits(cx,demand){return Ok(false)}let grant=cx.retained_grant();let cancel=cx.borrowed_original_cancel_token()?;let clock=cx.clock_source();let deadline=cx.deadline_us();let mut accepted=|_|!cancel.is_cancelled_now()&&clock().is_some_and(|now|now<deadline);let mut native=match self.encoding.take(){Some(original)=>NativeEncodeControl::resume(original,&mut accepted)?,None=>NativeEncodeControl::new_retained(&mut accepted)};
   let result=writer.step(&token,1,&mut native,grant);let progress=writer.normal_step_progress();let result=match result{Ok(Some(original))=>{*self.wire.original_mut().unwrap()=Some(original);self.phase=2;Ok(())},Ok(None)=>Ok(()),Err(original)=>Err(original)};self.encoding=Some(native.pause()?);let receipt=cx.consume_retained(progress).err();cx.consume_fuel(1);return match(result,receipt){(Ok(()),None)=>Ok(false),(Err(primary),receipt_refusal)=>Err(OriginalTurnFailure{primary:primary.into(),receipt_refusal,context_refusal:None}),(Ok(()),Some(refusal))=>Err(refusal.into())}
  }
  if self.phase==2{if close(&mut self.writer,cx)?{self.phase=3}return Ok(false)}
  if self.phase==3{
   let wire=self.wire.original().unwrap().as_ref().unwrap();if self.position<wire.len(){if !permits(cx,RetirementDemand{copy_bytes:1,depth:1,..Default::default()}){return Ok(false)}self.hash.as_mut().unwrap().update(&wire.as_bytes()[self.position..self.position+1]);self.position+=1;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()})?;cx.consume_fuel(1);return Ok(false)}
   if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}self.digest=self.hash.take().unwrap().finalize();self.position=0;self.phase=4;metadata(cx)?;return Ok(false)
  }
  if self.phase==4{if close(&mut self.wire,cx)?{self.phase=5}return Ok(false)}
  if self.phase==5{
   let slot=self.payload.original_mut().unwrap().as_mut().unwrap();if !self.reserved{let demand=RetirementDemand{capacity_bytes:64,depth:1,..Default::default()};if !permits(cx,demand){return Ok(false)}let result=slot.token.try_reserve_exact(64);let progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:slot.token.capacity(),..Default::default()};let receipt=cx.consume_retained(progress).err();cx.consume_fuel(1);self.reserved=true;return match(result,receipt){(Ok(()),None)=>Ok(false),(Err(_),receipt_refusal)=>Err(OriginalTurnFailure{primary:allocation("slot token allocation failed").with_retained_progress(progress).into(),receipt_refusal,context_refusal:None}),(Ok(()),Some(refusal))=>Err(refusal.into())}}
   if self.position<64{if !permits(cx,RetirementDemand{copy_bytes:1,depth:1,..Default::default()}){return Ok(false)}let byte=self.digest[self.position/2];let nibble=if self.position%2==0{byte>>4}else{byte&15};slot.token.push(b"0123456789abcdef"[nibble as usize]as char);self.position+=1;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()})?;cx.consume_fuel(1);return Ok(false)}self.phase=6
  }
  if self.phase==6{if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}self.encoding=None;self.phase=7;metadata(cx)?;return Ok(true)}Ok(false)
 }
 pub fn donate(&mut self,output:&mut Option<PresentedMediaSlot>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.check_caller(cx)?;if self.closing||self.phase!=7||output.is_some()||!permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}*output=self.payload.take_original().ok_or_else(||invalid("completed slot body lost original custody"))?;metadata(cx)?;Ok(true)}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.check_caller(cx)?;self.closing=true;if !close(&mut self.writer,cx)?{return Ok(false)}if !close(&mut self.wire,cx)?{return Ok(false)}if !close(&mut self.buffer,cx)?{return Ok(false)}if !close(&mut self.payload,cx)?{return Ok(false)}if self.encoding.is_some()||self.hash.is_some(){if !permits(cx,RetirementDemand{depth:1,..Default::default()}){return Ok(false)}self.encoding=None;self.hash=None;metadata(cx)?;return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.writer.terminal_is_empty()&&self.wire.terminal_is_empty()&&self.buffer.terminal_is_empty()&&self.payload.terminal_is_empty()&&self.encoding.is_none()&&self.hash.is_none()}
}
struct SlotIdentity<'a>(&'a PresentedMediaSlot);
impl JsonWriteSource for SlotIdentity<'_>{
 fn node_at_path(&self,path:&[usize])->Result<JsonWriteNode<'_>,ValueError>{let slot=self.0;Ok(match path{[]=>JsonWriteNode::Array(8),[0]=>JsonWriteNode::String(&slot.window_id),[1]=>JsonWriteNode::String(&slot.node_id),[2]=>JsonWriteNode::String(&slot.node_key),[3]=>JsonWriteNode::String(&slot.plugin_id),[4]=>JsonWriteNode::String(&slot.controller_id),[5]=>JsonWriteNode::Number(semio_framework_value::Number::UInt(slot.app_instance_id as u64)),[6]=>JsonWriteNode::String(&slot.parent_document_id),[7]=>if slot.props.get("resource").is_some_and(|value|!value.is_null()){JsonWriteNode::Array(7)}else{JsonWriteNode::Null},[7,index,rest @ ..]if *index<7=>{let field=["kind","controllerId","appInstanceId","parentDocumentId","outputPort","revision","generation"][*index];return match slot.props.get("resource").and_then(|resource|resource.get(field)){Some(original)=>original.node_at_path(rest),None if rest.is_empty()=>Ok(JsonWriteNode::Null),_=>Err(invalid("original slot resource identity changed"))}},_=>return Err(invalid("original slot identity ordinal changed"))})}
 fn object_key_at_path(&self,_:&[usize],_:usize)->Result<&str,ValueError>{Err(invalid("original slot identity has no object frontier"))}
}

impl Drop for OriginalPresentedSlot{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original presented slot requires full paid source retirement before Drop")}}

